import React, { useState, useEffect, useRef } from 'react';
import './ShareModal.css';
import { getAuthToken } from '../../utils/fileUtils';

const ShareModal = ({ isOpen, onClose, onShare, item }) => {
  const [username, setUsername] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [suggestions, setSuggestions] = useState([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const wrapperRef = useRef(null);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target)) {
        setShowSuggestions(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    const fetchSuggestions = async () => {
      if (username.length < 2) {
        setSuggestions([]);
        return;
      }

      try {
        // Mock suggestions if API fails or for testing
        const mockSuggestions = [
          { id: 1, username: 'usuario1', email: 'usuario1@example.com' },
          { id: 2, username: 'admin', email: 'admin@example.com' },
          { id: 3, username: 'test', email: 'test@example.com' }
        ].filter(u => u.username.toLowerCase().includes(username.toLowerCase()));

        const response = await fetch(`/api/users/search?q=${encodeURIComponent(username)}`, {
          headers: {
            'Authorization': `Bearer ${getAuthToken()}`
          }
        });
        
        if (response.ok) {
          const data = await response.json();
          setSuggestions(data.users || []);
          setShowSuggestions(true);
        } else {
           // Fallback to mock if API is not implemented yet
           console.warn('API search failed, using mock data');
           setSuggestions(mockSuggestions);
           setShowSuggestions(true);
        }
      } catch (err) {
        console.error('Error fetching suggestions:', err);
        // Fallback to mock
        const mockSuggestions = [
          { id: 1, username: 'usuario1', email: 'usuario1@example.com' },
          { id: 2, username: 'admin', email: 'admin@example.com' },
          { id: 3, username: 'test', email: 'test@example.com' }
        ].filter(u => u.username.toLowerCase().includes(username.toLowerCase()));
        setSuggestions(mockSuggestions);
        setShowSuggestions(true);
      }
    };

    const timeoutId = setTimeout(fetchSuggestions, 300);
    return () => clearTimeout(timeoutId);
  }, [username]);

  if (!isOpen) return null;

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!username.trim()) return;

    setLoading(true);
    setError('');
    
    try {
      await onShare(item, username);
      setUsername('');
      onClose();
    } catch (err) {
      setError(err.message || 'Error al compartir');
    } finally {
      setLoading(false);
    }
  };

  const handleSelectSuggestion = (user) => {
    setUsername(user.username);
    setShowSuggestions(false);
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-content glassmorphism-modal" onClick={e => e.stopPropagation()}>
        <h3>Compartir "{item?.name}"</h3>
        
        <form onSubmit={handleSubmit}>
          <div className="input-group relative" ref={wrapperRef}>
            <label>Nombre de usuario destino:</label>
            <input
              type="text"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              placeholder="Ej: usuario123"
              autoFocus
              className="glassmorphism-input"
              autoComplete="off"
            />
            
            {showSuggestions && suggestions.length > 0 && (
              <div className="suggestions-list">
                {suggestions.map((user) => (
                  <div 
                    key={user.id} 
                    className="suggestion-item"
                    onClick={() => handleSelectSuggestion(user)}
                  >
                    <img 
                      src={user.avatarUrl || `https://ui-avatars.com/api/?name=${user.username}&background=random`} 
                      alt={user.username} 
                      className="suggestion-avatar"
                    />
                    <div className="suggestion-info">
                      <span className="suggestion-name">{user.username}</span>
                      {user.email && <span className="suggestion-email">{user.email}</span>}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {error && <div className="error-message">{error}</div>}

          <div className="modal-buttons">
            <button type="button" onClick={onClose} className="cancel-btn">
              Cancelar
            </button>
            <button 
              type="submit" 
              className="confirm-btn"
              disabled={loading || !username.trim()}
            >
              {loading ? 'Compartiendo...' : 'Compartir'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default ShareModal;
